CREATE TABLE roles (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TIMESTAMP, updated_at TIMESTAMP, name VARCHAR(30) NOT NULL UNIQUE);
CREATE TABLE users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TIMESTAMP, updated_at TIMESTAMP, username VARCHAR(50) NOT NULL UNIQUE, password VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, enabled BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE user_roles (user_id BIGINT NOT NULL, role_id BIGINT NOT NULL, PRIMARY KEY(user_id,role_id), CONSTRAINT fk_ur_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT fk_ur_role FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE);
CREATE TABLE profiles (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TIMESTAMP, updated_at TIMESTAMP, full_name VARCHAR(255) NOT NULL, brand_name VARCHAR(255) UNIQUE, title VARCHAR(255), short_description VARCHAR(500), bio TEXT, about_text TEXT, journey_text TEXT, profile_image VARCHAR(255), avatar_id BIGINT, email VARCHAR(255) UNIQUE, phone VARCHAR(255), location VARCHAR(255), github_url VARCHAR(255), linkedin_url VARCHAR(255), instagram_url VARCHAR(255), working_status VARCHAR(30));
CREATE TABLE projects (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TIMESTAMP, updated_at TIMESTAMP, title VARCHAR(255) NOT NULL, slug VARCHAR(255) NOT NULL UNIQUE, short_description VARCHAR(500), description TEXT, image VARCHAR(255), demo_url VARCHAR(255), github_url VARCHAR(255), client_name VARCHAR(255), status VARCHAR(30) NOT NULL, project_date TIMESTAMP);
CREATE TABLE skills (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TIMESTAMP, updated_at TIMESTAMP, name VARCHAR(255) NOT NULL UNIQUE, category VARCHAR(30) NOT NULL, level INT NOT NULL, icon VARCHAR(255), description VARCHAR(500));
CREATE TABLE services (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TIMESTAMP, updated_at TIMESTAMP, title VARCHAR(255) NOT NULL UNIQUE, description TEXT, icon VARCHAR(255), features TEXT, display_order INT);
CREATE TABLE statistics (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TIMESTAMP, updated_at TIMESTAMP, title VARCHAR(255) NOT NULL UNIQUE, value VARCHAR(255) NOT NULL, icon VARCHAR(255), display_order INT);
CREATE TABLE experiences (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TIMESTAMP, updated_at TIMESTAMP, company VARCHAR(255) NOT NULL, position VARCHAR(255) NOT NULL, description TEXT, start_date DATE NOT NULL, end_date DATE, is_current BOOLEAN NOT NULL);
CREATE TABLE contact_messages (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TIMESTAMP, updated_at TIMESTAMP, name VARCHAR(255) NOT NULL, email VARCHAR(255) NOT NULL, phone VARCHAR(255), message TEXT NOT NULL, is_read BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE media (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TIMESTAMP, updated_at TIMESTAMP, file_name VARCHAR(255) NOT NULL, data BYTEA NOT NULL, content_type VARCHAR(100) NOT NULL, size BIGINT NOT NULL, type VARCHAR(30) NOT NULL);
